INSERT OR IGNORE INTO stories (id, date, month, summary_en, html_en, source_url, published) VALUES ('2026-02-10-cyprus-twice-postponed', '2026-02-10', '2026-02', 'A target of 1 January 2022 for mandatory B2G issuance was discussed by Cyprus''s Ministry of Finance and quietly dropped; a similar push around 2024 met the same fate.', '<h3>🇨🇾 Cyprus has proposed mandatory e-invoicing twice — and enacted it neither time</h3>
<p>Cyprus''s actual e-invoicing law is narrow: since 2019, central government bodies have had to be able to receive electronic invoices, extended to all remaining public sector bodies by April 2020. That''s genuinely all that''s legally required today — nothing obliges a supplier to actually send one, and there is no B2B mandate of any kind.</p>
<p>What makes Cyprus''s story worth watching isn''t what''s happened, but what''s been proposed and then quietly shelved. The Ministry of Finance floated a 1 January 2022 target for making B2G issuance mandatory, tied to a centralised government ERP system — the target passed with no mandate materialising. A similar push resurfaced around 2024, again tied to the same ERP rollout, and again went nowhere. Neither attempt reached actual legislation.</p>
<p>The practical lesson for anyone tracking Cyprus: treat the next announcement, whenever it comes, with the same caution these two received. Advisor commentary and industry blogs have periodically reported Cyprus as "about to" mandate e-invoicing for several years running — the only reliable signal is legislation actually passed, not a ministry discussion or a target date attached to an IT project.</p>', 'https://ec.europa.eu/digital-building-blocks/sites/display/DIGITAL/eInvoicing+in+Cyprus', 1);
INSERT OR IGNORE INTO story_countries (story_id, country_id) SELECT '2026-02-10-cyprus-twice-postponed', id FROM countries WHERE name_en = 'Cyprus';
INSERT OR IGNORE INTO story_translations (story_id, lang, title, summary, html) VALUES ('2026-02-10-cyprus-twice-postponed', 'en', 'Cyprus has proposed mandatory e-invoicing twice — and enacted it neither time', 'A target of 1 January 2022 for mandatory B2G issuance was discussed by Cyprus''s Ministry of Finance and quietly dropped; a similar push around 2024 met the same fate.', '<h3>🇨🇾 Cyprus has proposed mandatory e-invoicing twice — and enacted it neither time</h3>
<p>Cyprus''s actual e-invoicing law is narrow: since 2019, central government bodies have had to be able to receive electronic invoices, extended to all remaining public sector bodies by April 2020. That''s genuinely all that''s legally required today — nothing obliges a supplier to actually send one, and there is no B2B mandate of any kind.</p>
<p>What makes Cyprus''s story worth watching isn''t what''s happened, but what''s been proposed and then quietly shelved. The Ministry of Finance floated a 1 January 2022 target for making B2G issuance mandatory, tied to a centralised government ERP system — the target passed with no mandate materialising. A similar push resurfaced around 2024, again tied to the same ERP rollout, and again went nowhere. Neither attempt reached actual legislation.</p>
<p>The practical lesson for anyone tracking Cyprus: treat the next announcement, whenever it comes, with the same caution these two received. Advisor commentary and industry blogs have periodically reported Cyprus as "about to" mandate e-invoicing for several years running — the only reliable signal is legislation actually passed, not a ministry discussion or a target date attached to an IT project.</p>');
INSERT OR IGNORE INTO story_translations (story_id, lang, title, summary, html) VALUES ('2026-02-10-cyprus-twice-postponed', 'es', 'Chipre ha propuesto la facturación electrónica obligatoria dos veces — y no la ha promulgado ninguna', 'Un objetivo del 1 de enero de 2022 para la emisión B2G obligatoria fue discutido por el Ministerio de Hacienda de Chipre y abandonado silenciosamente; un impulso similar en torno a 2024 corrió la misma suerte.', '<h3>🇨🇾 Chipre ha propuesto la facturación electrónica obligatoria dos veces — y no la ha promulgado ninguna</h3>
<p>La ley de facturación electrónica real de Chipre es limitada: desde 2019, los organismos del gobierno central han tenido que poder recibir facturas electrónicas, ampliado a todos los demás organismos del sector público en abril de 2020. Eso es genuinamente todo lo que se exige legalmente hoy — nada obliga a un proveedor a enviar realmente una, y no existe ningún mandato B2B de ningún tipo.</p>
<p>Lo que hace que la historia de Chipre merezca la pena seguir no es lo que ha ocurrido, sino lo que se ha propuesto y luego archivado silenciosamente. El Ministerio de Hacienda planteó un objetivo del 1 de enero de 2022 para hacer obligatoria la emisión B2G, vinculado a un sistema ERP gubernamental centralizado — el objetivo pasó sin que se materializara ningún mandato. Un impulso similar resurgió alrededor de 2024, de nuevo vinculado al mismo despliegue de ERP, y de nuevo no llegó a nada. Ninguno de los dos intentos llegó a convertirse en legislación real.</p>
<p>La lección práctica para quien siga a Chipre: trate el próximo anuncio, cuando llegue, con la misma cautela que recibieron estos dos. Los comentarios de asesores y los blogs del sector han informado periódicamente durante varios años seguidos de que Chipre está "a punto de" hacer obligatoria la facturación electrónica — la única señal fiable es la legislación realmente aprobada, no una discusión ministerial ni una fecha objetivo vinculada a un proyecto informático.</p>');
INSERT OR IGNORE INTO story_translations (story_id, lang, title, summary, html) VALUES ('2026-02-10-cyprus-twice-postponed', 'de', 'Zypern hat zweimal eine verpflichtende E-Rechnung vorgeschlagen — und keine davon umgesetzt', 'Ein für den 1. Januar 2022 diskutiertes Ziel für die verpflichtende B2G-Ausstellung wurde vom zypriotischen Finanzministerium eingebracht und still fallengelassen; ein ähnlicher Vorstoß um 2024 erlitt dasselbe Schicksal.', '<h3>🇨🇾 Zypern hat zweimal eine verpflichtende E-Rechnung vorgeschlagen — und keine davon umgesetzt</h3>
<p>Zyperns tatsächliches E-Rechnungsgesetz ist eng gefasst: Seit 2019 müssen zentrale Regierungsstellen elektronische Rechnungen empfangen können, bis April 2020 auf alle übrigen öffentlichen Stellen ausgeweitet. Das ist tatsächlich alles, was heute gesetzlich vorgeschrieben ist — nichts verpflichtet einen Lieferanten, tatsächlich eine zu versenden, und es gibt keine B2B-Pflicht jeglicher Art.</p>
<p>Was Zyperns Geschichte beobachtenswert macht, ist nicht das, was geschehen ist, sondern das, was vorgeschlagen und dann still zu den Akten gelegt wurde. Das Finanzministerium brachte ein für den 1. Januar 2022 vorgesehenes Ziel für die verpflichtende B2G-Ausstellung ins Spiel, gekoppelt an ein zentralisiertes staatliches ERP-System — der Termin verstrich, ohne dass eine Pflicht zustande kam. Ein ähnlicher Vorstoß tauchte um 2024 erneut auf, wiederum an dieselbe ERP-Einführung gekoppelt, und führte erneut zu nichts. Keiner der beiden Versuche mündete in tatsächliche Gesetzgebung.</p>
<p>Die praktische Lehre für jeden, der Zypern verfolgt: Behandeln Sie die nächste Ankündigung, wann immer sie kommt, mit derselben Vorsicht wie diese beiden. Beraterkommentare und Branchenblogs haben über mehrere Jahre hinweg immer wieder berichtet, Zypern stehe "kurz davor", die E-Rechnung verpflichtend zu machen — das einzig verlässliche Signal ist tatsächlich verabschiedete Gesetzgebung, keine Ministeriumsdiskussion oder ein an ein IT-Projekt gekoppelter Zieltermin.</p>');
INSERT OR IGNORE INTO story_translations (story_id, lang, title, summary, html) VALUES ('2026-02-10-cyprus-twice-postponed', 'fr', 'Chypre a proposé la facturation électronique obligatoire à deux reprises — sans jamais l''adopter', 'Un objectif du 1er janvier 2022 pour l''émission B2G obligatoire a été discuté par le ministère des Finances chypriote puis discrètement abandonné ; une initiative similaire vers 2024 a connu le même sort.', '<h3>🇨🇾 Chypre a proposé la facturation électronique obligatoire à deux reprises — sans jamais l''adopter</h3>
<p>La véritable loi chypriote sur la facturation électronique est étroite : depuis 2019, les organismes du gouvernement central doivent pouvoir recevoir des factures électroniques, extension étendue à tous les autres organismes du secteur public d''ici avril 2020. C''est véritablement tout ce qui est légalement requis aujourd''hui — rien n''oblige un fournisseur à en envoyer réellement une, et il n''existe aucune obligation B2B d''aucune sorte.</p>
<p>Ce qui rend l''histoire de Chypre digne d''intérêt n''est pas ce qui s''est passé, mais ce qui a été proposé puis discrètement mis de côté. Le ministère des Finances a évoqué un objectif du 1er janvier 2022 pour rendre l''émission B2G obligatoire, lié à un système ERP gouvernemental centralisé — l''échéance est passée sans qu''aucune obligation ne se matérialise. Une initiative similaire a refait surface vers 2024, à nouveau liée au même déploiement ERP, et n''a de nouveau abouti à rien. Aucune des deux tentatives n''a débouché sur une véritable législation.</p>
<p>La leçon pratique pour quiconque suit Chypre : traitez la prochaine annonce, quand elle viendra, avec la même prudence que ces deux-là. Les commentaires d''experts et les blogs du secteur ont périodiquement rapporté, année après année, que Chypre était "sur le point" de rendre la facturation électronique obligatoire — le seul signal fiable est une législation réellement adoptée, non une discussion ministérielle ou une date cible liée à un projet informatique.</p>');

INSERT OR IGNORE INTO stories (id, date, month, summary_en, html_en, source_url, published) VALUES ('2026-06-05-cyprus-2030-floor-regardless', '2026-06-05', '2026-06', 'With no confirmed domestic timetable for B2B e-invoicing, the one date Cypriot businesses can actually plan around is ViDA''s confirmed 1 July 2030 cross-border requirement.', '<h3>🇨🇾 Whatever Cyprus decides domestically, the 2030 EU floor still applies</h3>
<p>For a business trying to plan around Cyprus''s e-invoicing landscape, the honest answer is that there isn''t much of a domestic timeline to plan around. No B2B mandate exists, no confirmed date for one has ever been set, and the two previous attempts to mandate even B2G issuance — targeted for 2022 and again around 2024 — were both quietly dropped rather than delayed to a new date.</p>
<p>What is certain, regardless of anything Cyprus decides domestically, is the EU''s own floor: the VAT in the Digital Age (ViDA) directive requires structured e-invoicing and digital reporting for intra-Community B2B transactions from 1 July 2030. That date doesn''t depend on Cypriot legislation at all — it''s confirmed EU law that applies uniformly across all Member States.</p>
<p>For Cypriot businesses trading with other EU countries, that makes 2030 the one planning horizon worth taking seriously today, rather than waiting for a domestic mandate that has twice failed to arrive. Businesses supplying Cypriot public bodies can also get ahead of any eventual domestic mandate at low cost, since voluntary e-invoicing via Peppol or the government''s gov.cy portal is already fully functional — it simply isn''t required yet.</p>', 'https://taxation-customs.ec.europa.eu/taxation/vat/vat-digital-age-vida_en', 1);
INSERT OR IGNORE INTO story_countries (story_id, country_id) SELECT '2026-06-05-cyprus-2030-floor-regardless', id FROM countries WHERE name_en = 'Cyprus';
INSERT OR IGNORE INTO story_translations (story_id, lang, title, summary, html) VALUES ('2026-06-05-cyprus-2030-floor-regardless', 'en', 'Whatever Cyprus decides domestically, the 2030 EU floor still applies', 'With no confirmed domestic timetable for B2B e-invoicing, the one date Cypriot businesses can actually plan around is ViDA''s confirmed 1 July 2030 cross-border requirement.', '<h3>🇨🇾 Whatever Cyprus decides domestically, the 2030 EU floor still applies</h3>
<p>For a business trying to plan around Cyprus''s e-invoicing landscape, the honest answer is that there isn''t much of a domestic timeline to plan around. No B2B mandate exists, no confirmed date for one has ever been set, and the two previous attempts to mandate even B2G issuance — targeted for 2022 and again around 2024 — were both quietly dropped rather than delayed to a new date.</p>
<p>What is certain, regardless of anything Cyprus decides domestically, is the EU''s own floor: the VAT in the Digital Age (ViDA) directive requires structured e-invoicing and digital reporting for intra-Community B2B transactions from 1 July 2030. That date doesn''t depend on Cypriot legislation at all — it''s confirmed EU law that applies uniformly across all Member States.</p>
<p>For Cypriot businesses trading with other EU countries, that makes 2030 the one planning horizon worth taking seriously today, rather than waiting for a domestic mandate that has twice failed to arrive. Businesses supplying Cypriot public bodies can also get ahead of any eventual domestic mandate at low cost, since voluntary e-invoicing via Peppol or the government''s gov.cy portal is already fully functional — it simply isn''t required yet.</p>');
INSERT OR IGNORE INTO story_translations (story_id, lang, title, summary, html) VALUES ('2026-06-05-cyprus-2030-floor-regardless', 'es', 'Decida lo que decida Chipre a nivel nacional, el suelo de la UE de 2030 sigue aplicándose', 'Sin un calendario nacional confirmado para la facturación electrónica B2B, la única fecha en torno a la cual las empresas chipriotas pueden planificar realmente es el requisito transfronterizo confirmado de ViDA del 1 de julio de 2030.', '<h3>🇨🇾 Decida lo que decida Chipre a nivel nacional, el suelo de la UE de 2030 sigue aplicándose</h3>
<p>Para una empresa que intenta planificar en torno al panorama de facturación electrónica de Chipre, la respuesta honesta es que no hay mucho calendario nacional en torno al cual planificar. No existe ningún mandato B2B, nunca se ha fijado una fecha confirmada para uno, y los dos intentos anteriores de hacer obligatoria incluso la emisión B2G — previstos para 2022 y de nuevo alrededor de 2024 — fueron ambos abandonados silenciosamente en lugar de aplazados a una nueva fecha.</p>
<p>Lo que es seguro, con independencia de lo que decida Chipre a nivel nacional, es el propio suelo de la UE: la directiva del IVA en la Era Digital (ViDA) exige capacidad de facturación electrónica estructurada y reporte digital para las transacciones B2B intracomunitarias a partir del 1 de julio de 2030. Esa fecha no depende en absoluto de la legislación chipriota — es derecho de la UE confirmado que se aplica de manera uniforme en todos los Estados miembros.</p>
<p>Para las empresas chipriotas que comercian con otros países de la UE, eso convierte a 2030 en el único horizonte de planificación que vale la pena tomar en serio hoy, en lugar de esperar un mandato nacional que dos veces no ha llegado a materializarse. Las empresas que abastecen a organismos públicos chipriotas también pueden adelantarse a cualquier eventual mandato nacional a bajo coste, ya que la facturación electrónica voluntaria a través de Peppol o el portal gov.cy del gobierno ya es totalmente funcional — simplemente aún no es obligatoria.</p>');
INSERT OR IGNORE INTO story_translations (story_id, lang, title, summary, html) VALUES ('2026-06-05-cyprus-2030-floor-regardless', 'de', 'Was auch immer Zypern innerstaatlich entscheidet, die EU-Untergrenze von 2030 gilt trotzdem', 'Ohne bestätigten inländischen Zeitplan für die B2B-E-Rechnung ist das einzige Datum, auf das sich zypriotische Unternehmen tatsächlich einstellen können, ViDAs bestätigte grenzüberschreitende Anforderung vom 1. Juli 2030.', '<h3>🇨🇾 Was auch immer Zypern innerstaatlich entscheidet, die EU-Untergrenze von 2030 gilt trotzdem</h3>
<p>Für ein Unternehmen, das versucht, sich auf Zyperns E-Rechnungslandschaft einzustellen, lautet die ehrliche Antwort, dass es kaum einen inländischen Zeitplan gibt, auf den man sich einstellen könnte. Es gibt keine B2B-Pflicht, nie wurde ein bestätigter Termin dafür festgelegt, und die beiden früheren Versuche, selbst die B2G-Ausstellung verpflichtend zu machen — anvisiert für 2022 und erneut um 2024 —, wurden beide still fallengelassen, statt auf einen neuen Termin verschoben zu werden.</p>
<p>Was unabhängig von jeder innerstaatlichen Entscheidung Zyperns feststeht, ist die eigene Untergrenze der EU: Die Richtlinie VAT in the Digital Age (ViDA) verlangt ab dem 1. Juli 2030 strukturierte E-Rechnungs- und digitale Meldefähigkeit für innergemeinschaftliche B2B-Umsätze. Dieses Datum hängt überhaupt nicht von zypriotischer Gesetzgebung ab — es ist bestätigtes EU-Recht, das einheitlich in allen Mitgliedstaaten gilt.</p>
<p>Für zypriotische Unternehmen, die mit anderen EU-Ländern handeln, macht das 2030 zum einzigen Planungshorizont, den man heute ernst nehmen sollte, statt auf eine inländische Pflicht zu warten, die zweimal nicht zustande gekommen ist. Unternehmen, die zypriotische öffentliche Stellen beliefern, können einer etwaigen künftigen inländischen Pflicht auch kostengünstig zuvorkommen, da die freiwillige E-Rechnung über Peppol oder das gov.cy-Portal der Regierung bereits voll funktionsfähig ist — sie ist lediglich noch nicht vorgeschrieben.</p>');
INSERT OR IGNORE INTO story_translations (story_id, lang, title, summary, html) VALUES ('2026-06-05-cyprus-2030-floor-regardless', 'fr', 'Quelle que soit la décision de Chypre au niveau national, le plancher de l''UE de 2030 s''applique quand même', 'Sans calendrier national confirmé pour la facturation électronique B2B, la seule date sur laquelle les entreprises chypriotes peuvent réellement se projeter est l''exigence transfrontalière confirmée de ViDA du 1er juillet 2030.', '<h3>🇨🇾 Quelle que soit la décision de Chypre au niveau national, le plancher de l''UE de 2030 s''applique quand même</h3>
<p>Pour une entreprise qui essaie de se projeter dans le paysage de la facturation électronique à Chypre, la réponse honnête est qu''il n''y a pas vraiment de calendrier national sur lequel se projeter. Aucune obligation B2B n''existe, aucune date confirmée n''a jamais été fixée pour cela, et les deux tentatives précédentes de rendre même l''émission B2G obligatoire — visées pour 2022 puis à nouveau vers 2024 — ont toutes deux été discrètement abandonnées plutôt que reportées à une nouvelle date.</p>
<p>Ce qui est certain, indépendamment de ce que Chypre décide au niveau national, c''est le propre plancher de l''UE : la directive TVA à l''ère numérique (ViDA) exige une capacité de facturation électronique structurée et de déclaration numérique pour les transactions B2B intracommunautaires à partir du 1er juillet 2030. Cette date ne dépend absolument pas de la législation chypriote — c''est un droit de l''UE confirmé qui s''applique uniformément dans tous les États membres.</p>
<p>Pour les entreprises chypriotes commerçant avec d''autres pays de l''UE, cela fait de 2030 le seul horizon de planification qu''il vaille la peine de prendre au sérieux aujourd''hui, plutôt que d''attendre une obligation nationale qui n''a par deux fois pas vu le jour. Les entreprises fournissant des organismes publics chypriotes peuvent également prendre les devants sur une éventuelle future obligation nationale à faible coût, la facturation électronique volontaire via Peppol ou le portail gov.cy du gouvernement étant déjà pleinement fonctionnelle — elle n''est simplement pas encore obligatoire.</p>');

